\set ON_ERROR_STOP on
DO $test$ DECLARE h text; persisted jsonb; replay jsonb; BEGIN
h:=private.financial_operation_hash('sale.cashier_inventory',private.canonical_financial_request_v1('sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb),'admin:00000000-0000-0000-0000-0000000000aa','lab-cash-a','lab-station-a');
SELECT response_payload INTO persisted FROM public.pos_financial_operations WHERE license_id='00000000-0000-0000-0000-000000000001' AND idempotency_key='lab-race-24-normal';
replay:=public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-race-24-normal',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb);
IF replay IS DISTINCT FROM persisted THEN RAISE EXCEPTION 'REPLAY_RECEIPT_CHANGED'; END IF;
BEGIN PERFORM public.pos_execute_financial_operation_v1('lab-license-a','lab-device-a','lab-device-token-a','lab-admin-session','lab-race-24-new-identity',h,'sale.cashier_inventory','{"cash_session_id":"lab-cash-a","sale":{"id":"lab-race-24","subtotal":20,"total":20,"payment_method":"cash","amount_paid":20,"balance_due":0,"change_amount":0},"items":[{"id":"lab-race-24-line","product_id":"lab-race-24-product","product_name":"Synthetic race 24","quantity":2,"unit_price":10,"line_subtotal":20,"line_total":20}],"payments":[{"id":"lab-race-24-payment","method":"cash","amount":20,"received_amount":20,"change_amount":0}],"restaurant_settlement":{"parent_order_id":"lab-race-24","parent_order_version":"2026-10-01T00:00:00Z"}}'::jsonb); RAISE EXCEPTION 'UNEXPECTED_SECOND_SETTLEMENT'; EXCEPTION WHEN SQLSTATE 'P0001' THEN IF SQLERRM NOT IN ('RESTAURANT_ORDER_ALREADY_PAID','RESTAURANT_ORDER_NOT_ACTIVE') THEN RAISE; END IF; END;
IF (SELECT stock FROM public.pos_products WHERE id='lab-race-24-product')<>18 OR (SELECT count(*) FROM public.pos_sales WHERE id LIKE 'lab-race-24%')<>1 OR (SELECT count(*) FROM public.pos_sale_payments WHERE sale_id LIKE 'lab-race-24%')<>1 OR (SELECT count(*) FROM public.pos_cash_movements WHERE sale_id LIKE 'lab-race-24%')<>1 OR (SELECT count(*) FROM public.pos_inventory_movements WHERE product_id='lab-race-24-product')<>1 THEN RAISE EXCEPTION 'REPLAY_DUPLICATED_EFFECTS'; END IF;
END $test$;
SELECT 'PASS_REPLAY_AND_SECOND_IDENTITY' result;